refentry.refsect1:
  &reftitle.examples;



    Esempio di pg_get_result


<?php
  $dbconn = pg_connect("dbname=publisher") or die("Impossibile connettersi");

  if (!pg_connection_busy($dbconn)) {
      pg_send_query($dbconn, "select * from authors; select count(*) from authors;");
  }

  $res1 = pg_get_result($dbconn);
  echo "Prima chiamata a pg_get_result(): $res1\n";
  $rows1 = pg_num_rows($res1);
  echo "$res1 ha $rows1 record\n\n";

  $res2 = pg_get_result($dbconn);
  echo "Seconda chiamata a pg_get_result(): $res2\n";
  $rows2 = pg_num_rows($res2);
  echo "$res2 ha $rows2 record\n";
?>


    &example.outputs;


Prima chiamata a pg_get_result(): Resource id #3
Resource id #3 ha 3 record

Seconda chiamata a pg_get_result(): Resource id #4
Resource id #4 ha 1 record
